from playwright.sync_api import sync_playwright
URL='http://127.0.0.1:28494'
with sync_playwright() as p:
 browser=p.chromium.launch(headless=True);ctx=browser.new_context();page=ctx.new_page();page.goto(URL);page.locator('#newDialog[open]').wait_for();page.locator('#newName').fill('副本分页');page.get_by_role('button',name='创建',exact=True).click();page.wait_for_function("document.querySelector('#workflowStatus').textContent.includes('待开始')");page.get_by_role('button',name='进入人工修订阶段').click();page.wait_for_function("document.querySelector('#workflowStatus').textContent.includes('人工修订')");page.get_by_role('button',name='进入人工修订模式').click();page.wait_for_function("document.querySelector('#workflowModeState').textContent.includes('已进入')");pid=page.evaluate('paperpilot.current.project.id');f=ctx.request.get(f'{URL}/api/projects/{pid}').json()['files'][0];url=f'{URL}/api/projects/{pid}/human-revision/drafts';payload={'target_kind':'file','target_path':f['path'],'base_version':f['version'],'expected_draft_updated_at':None}
 for i in range(35):
  r=ctx.request.post(url,data={**payload,'copy_id':f'copy-{i:02d}','content':f'分页草稿{i:02d}'});assert r.status==(200 if i==0 else 409),r.text()
 page.locator('#revisionCopiesRefresh').click();page.wait_for_function("document.querySelector('#revisionCopies').options.length===31");assert page.locator('#revisionCopiesMore').is_visible();page.locator('#revisionCopiesMore').click();page.wait_for_function("document.querySelector('#revisionCopies').options.length===36");assert page.locator('#revisionCopiesMore').is_hidden()
 option=page.locator('#revisionCopies option').filter(has_text='分页草稿01');key=option.get_attribute('value');page.locator('#revisionCopies').select_option(key);page.wait_for_function("document.querySelector('#revisionCopyPreview').value==='分页草稿01'")
 current=ctx.request.get(url).json()[0];r=ctx.request.post(url,data={**payload,'copy_id':key,'content':'已更新副本','expected_draft_updated_at':current['updated_at']});assert r.ok,r.text();page.locator('#revisionCopyRestore').click();page.wait_for_function("document.querySelector('#revisionCopyStatus').textContent.includes('副本已变化')");assert page.locator('#editor').input_value()!='分页草稿01';browser.close();print('pagination and stale selection passed')
